const cfg = $json || {};
if (!cfg.locationId) throw new Error('Missing Config.locationId');
if (!cfg.apiKey) throw new Error('Missing Config.apiKey');
if (!cfg.sheetId) throw new Error('Missing Config.sheetId');
if (!cfg.sheetName) throw new Error('Missing Config.sheetName');
if (!cfg.batchValue) throw new Error('Missing Config.batchValue');

const dryRun = !!cfg.dryRun;
const maxRows = Number(cfg.maxRows || 0);
const baseUrl = String(cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');

const headers = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

async function apiRequest({ method, path, body, fullUrl, raw = false }) {
  const options = {
    method,
    url: fullUrl || `${baseUrl}${path}`,
    headers: raw ? { Accept: 'text/csv' } : headers,
    json: !raw,
  };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, status: 200, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
      requestBody: body,
    };
  }
}

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];
    if (inQuotes) {
      if (ch === '"' && next === '"') { cell += '"'; i++; }
      else if (ch === '"') { inQuotes = false; }
      else { cell += ch; }
    } else {
      if (ch === '"') inQuotes = true;
      else if (ch === ',') { row.push(cell); cell = ''; }
      else if (ch === '\n') { row.push(cell); rows.push(row); row = []; cell = ''; }
      else if (ch === '\r') { }
      else { cell += ch; }
    }
  }
  if (cell.length || row.length) { row.push(cell); rows.push(row); }
  return rows;
}

function rowsToObjects(rows) {
  if (!rows.length) return [];
  const headers = rows[0].map((h) => String(h || '').trim());
  const out = [];
  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    const obj = {};
    headers.forEach((h, idx) => { if (h) obj[h] = r[idx] ?? ''; });
    const hasAny = Object.values(obj).some((v) => String(v || '').trim() !== '');
    if (hasAny) out.push(obj);
  }
  return out;
}

function nk(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''); }
function pick(obj, aliases) {
  const wanted = new Set(aliases.map(nk));
  for (const [k, v] of Object.entries(obj)) {
    if (wanted.has(nk(k)) && String(v ?? '').trim() !== '') return String(v).trim();
  }
  return '';
}
function toNum(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : null;
}
function toDate(v) {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}
function getArrayPayload(obj) {
  if (Array.isArray(obj)) return obj;
  if (Array.isArray(obj?.customFields)) return obj.customFields;
  if (Array.isArray(obj?.data?.customFields)) return obj.data.customFields;
  if (Array.isArray(obj?.data)) return obj.data;
  return [];
}

const urls = [];
urls.push(`https://docs.google.com/spreadsheets/d/${cfg.sheetId}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(cfg.sheetName)}`);
if (cfg.sheetGid) urls.push(`https://docs.google.com/spreadsheets/d/${cfg.sheetId}/export?format=csv&gid=${encodeURIComponent(String(cfg.sheetGid))}`);
urls.push(`https://docs.google.com/spreadsheets/d/${cfg.sheetId}/export?format=csv`);

let csvText = null;
let csvErr = null;
for (const url of urls) {
  const r = await apiRequest.call(this, { method: 'GET', fullUrl: url, raw: true });
  if (r.ok) {
    csvText = typeof r.data === 'string' ? r.data : String(r.data || '');
    if (csvText.trim()) break;
  } else {
    csvErr = r;
  }
}
if (!csvText) throw new Error(`Failed to read Google Sheet CSV: ${JSON.stringify(csvErr)}`);

let records = rowsToObjects(parseCsv(csvText));
if (!records.length) throw new Error('No rows found in source sheet');
if (maxRows > 0) records = records.slice(0, maxRows);

const cfRes = await apiRequest.call(this, { method: 'GET', path: `/locations/${cfg.locationId}/customFields?model=contact` });
if (!cfRes.ok) throw new Error(`Failed to fetch contact custom fields: ${cfRes.status} ${JSON.stringify(cfRes.data)}`);
const customFields = getArrayPayload(cfRes.data);
const fieldByName = new Map(customFields.map((f) => [String(f?.name || '').trim(), f]));

const batchField = fieldByName.get('Batch_Upload');
if (!batchField?.id) throw new Error('Batch_Upload field not found. Create it first.');

const apolloFieldNames = [
  'Apollo Contact Id','Apollo Account Id','Apollo Email Status','Apollo Primary Email Source','Apollo Primary Email Verification Source',
  'Apollo Email Confidence','Apollo Primary Email Catch-all Status','Apollo Primary Email Last Verified At','Apollo Seniority','Apollo Departments',
  'Apollo Sub Departments','Apollo Company Employees','Apollo Industry','Apollo Keywords','Apollo Person LinkedIn URL',
  'Apollo Company LinkedIn URL','Apollo Facebook URL','Apollo Twitter URL','Apollo Technologies','Apollo Annual Revenue',
  'Apollo Total Funding','Apollo Latest Funding','Apollo Latest Funding Amount','Apollo Last Raised At','Apollo Subsidiary Of',
  'Apollo Secondary Email','Apollo Secondary Email Source','Apollo Secondary Email Status','Apollo Secondary Email Verification Source',
  'Apollo Tertiary Email','Apollo Tertiary Email Source','Apollo Tertiary Email Status','Apollo Tertiary Email Verification Source',
  'Apollo Primary Intent Topic','Apollo Primary Intent Score','Apollo Secondary Intent Topic','Apollo Secondary Intent Score','Apollo Qualify Contact'
];

const missingApolloFields = apolloFieldNames.filter((n) => !fieldByName.get(n)?.id);
if (missingApolloFields.length) {
  throw new Error(`Missing required Apollo custom fields in GHL: ${missingApolloFields.join(', ')}`);
}

function mapApollo(rec) {
  return {
    'Apollo Contact Id': pick(rec,['Apollo Contact Id','apollo_contact_id']),
    'Apollo Account Id': pick(rec,['Apollo Account Id','apollo_account_id']),
    'Apollo Email Status': pick(rec,['Email Status','Apollo Email Status','email_status']),
    'Apollo Primary Email Source': pick(rec,['Primary Email Source','Apollo Primary Email Source']),
    'Apollo Primary Email Verification Source': pick(rec,['Primary Email Verification Source','Apollo Primary Email Verification Source']),
    'Apollo Email Confidence': toNum(pick(rec,['Email Confidence','Apollo Email Confidence'])),
    'Apollo Primary Email Catch-all Status': pick(rec,['Primary Email Catch-all Status','Apollo Primary Email Catch-all Status']),
    'Apollo Primary Email Last Verified At': toDate(pick(rec,['Primary Email Last Verified At','Apollo Primary Email Last Verified At'])),
    'Apollo Seniority': pick(rec,['Seniority','Apollo Seniority']),
    'Apollo Departments': pick(rec,['Departments','Apollo Departments']),
    'Apollo Sub Departments': pick(rec,['Sub Departments','Apollo Sub Departments']),
    'Apollo Company Employees': toNum(pick(rec,['# Employees','Apollo Company Employees'])),
    'Apollo Industry': pick(rec,['Industry','Apollo Industry']),
    'Apollo Keywords': pick(rec,['Keywords','Apollo Keywords']),
    'Apollo Person LinkedIn URL': pick(rec,['Person Linkedin Url','Apollo Person LinkedIn URL']),
    'Apollo Company LinkedIn URL': pick(rec,['Company Linkedin Url','Apollo Company LinkedIn URL']),
    'Apollo Facebook URL': pick(rec,['Facebook Url','Apollo Facebook URL']),
    'Apollo Twitter URL': pick(rec,['Twitter Url','Apollo Twitter URL']),
    'Apollo Technologies': pick(rec,['Technologies','Apollo Technologies']),
    'Apollo Annual Revenue': toNum(pick(rec,['Annual Revenue','Apollo Annual Revenue'])),
    'Apollo Total Funding': toNum(pick(rec,['Total Funding','Apollo Total Funding'])),
    'Apollo Latest Funding': pick(rec,['Latest Funding','Apollo Latest Funding']),
    'Apollo Latest Funding Amount': toNum(pick(rec,['Latest Funding Amount','Apollo Latest Funding Amount'])),
    'Apollo Last Raised At': toDate(pick(rec,['Last Raised At','Apollo Last Raised At'])),
    'Apollo Subsidiary Of': pick(rec,['Subsidiary of','Apollo Subsidiary Of']),
    'Apollo Secondary Email': pick(rec,['Secondary Email','Apollo Secondary Email']),
    'Apollo Secondary Email Source': pick(rec,['Secondary Email Source','Apollo Secondary Email Source']),
    'Apollo Secondary Email Status': pick(rec,['Secondary Email Status','Apollo Secondary Email Status']),
    'Apollo Secondary Email Verification Source': pick(rec,['Secondary Email Verification Source','Apollo Secondary Email Verification Source']),
    'Apollo Tertiary Email': pick(rec,['Tertiary Email','Apollo Tertiary Email']),
    'Apollo Tertiary Email Source': pick(rec,['Tertiary Email Source','Apollo Tertiary Email Source']),
    'Apollo Tertiary Email Status': pick(rec,['Tertiary Email Status','Apollo Tertiary Email Status']),
    'Apollo Tertiary Email Verification Source': pick(rec,['Tertiary Email Verification Source','Apollo Tertiary Email Verification Source']),
    'Apollo Primary Intent Topic': pick(rec,['Primary Intent Topic','Apollo Primary Intent Topic']),
    'Apollo Primary Intent Score': toNum(pick(rec,['Primary Intent Score','Apollo Primary Intent Score'])),
    'Apollo Secondary Intent Topic': pick(rec,['Secondary Intent Topic','Apollo Secondary Intent Topic']),
    'Apollo Secondary Intent Score': toNum(pick(rec,['Secondary Intent Score','Apollo Secondary Intent Score'])),
    'Apollo Qualify Contact': pick(rec,['Qualify Contact','Apollo Qualify Contact']),
  };
}

const results = [];
for (const rec of records) {
  const firstName = pick(rec,['First Name','first_name','firstname']);
  const lastName = pick(rec,['Last Name','last_name','lastname']);
  const email = pick(rec,['Email','email']);
  const phone = pick(rec,['Mobile Phone','mobile_phone','Work Direct Phone','Corporate Phone','phone']);
  const companyName = pick(rec,['Company Name','company_name','company']);

  if (!email && !phone) {
    results.push({ status: 'skipped', reason: 'missing email and phone' });
    continue;
  }

  const ap = mapApollo(rec);
  const updateEntries = [{ id: batchField.id, value: cfg.batchValue }];
  for (const [name, val] of Object.entries(ap)) {
    if (val === null || val === undefined || val === '') continue;
    const fid = fieldByName.get(name)?.id;
    if (fid) updateEntries.push({ id: fid, value: val });
  }

  if (dryRun) {
    results.push({ status: 'planned', email, phone, firstName, lastName, customFieldsToSet: updateEntries.length });
    continue;
  }

  const upsertBody = {
    locationId: cfg.locationId,
    email: email || undefined,
    phone: phone || undefined,
    firstName: firstName || undefined,
    lastName: lastName || undefined,
    companyName: companyName || undefined,
  };
  Object.keys(upsertBody).forEach((k) => upsertBody[k] === undefined && delete upsertBody[k]);

  const upsertRes = await apiRequest.call(this, { method: 'POST', path: '/contacts/upsert', body: upsertBody });
  if (!upsertRes.ok) {
    results.push({ status: 'error', step: 'upsert', email, details: upsertRes.data });
    continue;
  }
  const contactId = upsertRes.data?.contact?.id || upsertRes.data?.id || upsertRes.data?.contactId;
  if (!contactId) {
    results.push({ status: 'error', step: 'resolve_contact_id', email, details: upsertRes.data });
    continue;
  }

  const customFieldObject = Object.fromEntries(updateEntries.map((e) => [e.id, e.value]));
  const stampBodies = [
    { locationId: cfg.locationId, customField: customFieldObject },
    { customField: customFieldObject },
    { locationId: cfg.locationId, customFields: updateEntries.map((e) => ({ id: e.id, value: e.value })) },
    { customFields: updateEntries.map((e) => ({ id: e.id, value: e.value })) },
    { locationId: cfg.locationId, customFields: updateEntries.map((e) => ({ id: e.id, field_value: e.value })) },
    { customFields: updateEntries.map((e) => ({ id: e.id, field_value: e.value })) },
  ];

  let stampOk = false;
  let stampErr = null;
  for (const body of stampBodies) {
    const sr = await apiRequest.call(this, { method: 'PUT', path: `/contacts/${contactId}`, body });
    if (sr.ok) { stampOk = true; break; }
    stampErr = sr;
  }

  if (!stampOk) {
    results.push({ status: 'error', step: 'custom_field_update', contactId, email, details: stampErr?.data || stampErr });
    continue;
  }

  results.push({ status: 'imported', contactId, email, customFieldsSet: updateEntries.length });
}

return [{
  json: {
    ok: true,
    dryRun,
    sourceSheet: cfg.sheetName,
    sourceRecords: records.length,
    imported: results.filter((r) => r.status === 'imported').length,
    planned: results.filter((r) => r.status === 'planned').length,
    skipped: results.filter((r) => r.status === 'skipped').length,
    errors: results.filter((r) => r.status === 'error').length,
    RESULTS: results,
  },
}];
